import { signRewards, addRewards, editRewards } from '@/api/marketing';

export default {
  data() {
    return {
      columns: [
        {
          title: '类型',
          slot: 'type',
        },
        {
          title: '天数',
          key: 'days',
        },
        {
          title: '奖励积分',
          key: 'point',
        },
        {
          title: '奖励经验',
          key: 'exp',
        },
        {
          title: '操作',
          slot: 'action',
        },
      ],
      rewards: [],
      total: 0,
      tableParams: {
        type: '0',
        page: 1,
        limit: 15,
      },
    };
  },
  created() {
    this.signRewards();
  },
  methods: {
    // 获取签到奖励
    signRewards() {
      signRewards(this.tableParams).then((res) => {
        this.rewards = res.data.list;
        this.total = res.data.count;
      });
    },
    // 切换类型
    tabsChange() {
      this.tableParams.page = 1;
      this.signRewards();
    },
    // 分页
    pageChange(page) {
      this.tableParams.page = page;
      this.signRewards();
    },
    // 添加
    add() {
      this.$modalForm(addRewards({ type: this.tableParams.type })).then(() =>
        this.signRewards()
      );
    },
    // 编辑
    edit(row) {
      this.$modalForm(editRewards(row.id)).then(() => this.signRewards());
    },
    // 删除
    remove(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `/setting/sign/del_rewards/${row.id}`,
        method: 'DELETE',
        ids: '',
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.signRewards();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
  },
};
